CREATE TABLE IF NOT EXISTS levels (id TEXT PRIMARY KEY, name TEXT, creator TEXT, song TEXT, difficulty TEXT, rating REAL, side_rating REAL, enjoyment_avg REAL, enjoyment_votes INTEGER, tags_json TEXT, tier INTEGER, side_tier INTEGER);
CREATE INDEX IF NOT EXISTS idx_levels_name ON levels(name);
CREATE TABLE IF NOT EXISTS community_ideas (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT NOT NULL, author TEXT NOT NULL DEFAULT 'Anonymous', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
